(5661932, 823044, 39427, '<td valign="top">lovely.  9</td>', 'lovely.  9', '2009-09-25 11:36:09.000000', NULL, 1),
(5661933, 823448, 15711, '<td valign="top">I''m one of those who hates foreground bokeh, but I won''t take off for that.  Great tones.  It has an odd uphill feel.  Maybe that was your intent.  Man, that poor girl needs to eat.  Her ribs are jutting out. LOL</td>', 'I''m one of those who hates foreground bokeh, but I won''t take off for that.  Great tones.  It has an odd uphill feel.  Maybe that was your intent.  Man, that poor girl needs to eat.  Her ribs are jutting out. LOL', '2009-09-25 11:37:13.000000', NULL, 1),
(5661934, 823280, 15711, '<td valign="top">This is lovely and quite artful.  I like how you centered her.  That doesn''t always work but it did.  Great light. 8</td>', 'This is lovely and quite artful.  I like how you centered her.  That doesn''t always work but it did.  Great light. 8', '2009-09-25 11:37:53.000000', NULL, 1),
(5661936, 823533, 15711, '<td valign="top">EXCELLENT use of light and shadow.  WOW - I rarely give 10''s but it''s certainly worthy.  Great job.</td>', 'EXCELLENT use of light and shadow.  WOW - I rarely give 10''s but it''s certainly worthy.  Great job.', '2009-09-25 11:39:09.000000', NULL, 1),
(5661941, 823513, 15711, '<td valign="top">I like the artful approach.  The bi-color is great. Has an ethereal quality.</td>', 'I like the artful approach.  The bi-color is great. Has an ethereal quality.', '2009-09-25 11:40:57.000000', NULL, 1),
(5661942, 822596, 15711, '<td valign="top">Makes me think of an Abercrombie and Fitch guy.  I hope he''s 18. LOL</td>', 'Makes me think of an Abercrombie and Fitch guy.  I hope he''s 18. LOL', '2009-09-25 11:43:12.000000', NULL, 1),
