INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5671316, 823200, 93859, '<td valign="top">Great photo. Realistic and sober. I like the mirror effect. It reminds me of Sabine from "The umbearable lightness of the soul". Good job.</td>', 'Great photo. Realistic and sober. I like the mirror effect. It reminds me of Sabine from "The umbearable lightness of the soul". Good job.', '2009-10-02 11:31:56.000000', NULL, 0),
(5671340, 823448, 86447, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Lallisig:</b></div><hr/><i> ... really hate it when people do that, judge me and my photography all you want, I do not care, but why are you knocking on her appearance? She is very fit and has a great body... </i></td></tr></table> <br/> <br/>I''m sure she''s beautiful and none of the comments were directed at her, but for the photographer for making her appear this way.  There does seem to be a trend to the comments... so perhaps notice should be taken of that for making models appear at their best?  I don''t think that many folks brave enough to say something about it are<i> all</i> on the wrong track.  <br/> <br/>Your model should take comfort in the fact that most voters/commenters will put the blame or credit on how the model looks on the photographer who lit her and posed her to appear a certain way. <br/> <br/>Many congrats to you again, on your ribbon and for your wonderful talent as a photographer.</td>', 'Originally posted by Lallisig: ... really hate it when people do that, judge me and my photography all you want, I do not care, but why are you knocking on her appearance? She is very fit and has a great body...   I''m sure she''s beautiful and none of the comments were directed at her, but for the photographer for making her appear this way.  There does seem to be a trend to the comments... so perhaps notice should be taken of that for making models appear at their best?  I don''t think that many folks brave enough to say something about it are all on the wrong track.   Your model should take comfort in the fact that most voters/commenters will put the blame or credit on how the model looks on the photographer who lit her and posed her to appear a certain way.  Many congrats to you again, on your ribbon and for your wonderful talent as a photographer.', '2009-10-02 11:47:36.000000', NULL, 0),
